insert overwrite table ${schema}.ads_sr_data_warehouse_tc_antifraud_limit_1h
partition (grass_region = ${grass_region}, grass_date, hour)
select  T1.shop_id
        ,T1.update_time
        ,T1.order_ovl
        ,T2.order_cnt

        ,T1.local_date
        ,T1.local_hour
from    (
    select  *
    from    srdi_mart.dws_sr_data_warehouse_tc_antifraud_ovl_1h
    where   grass_region = ${grass_region}
      and   regional_date = ${regional_date}
      and   regional_hour = ${regional_hour}
) as T1
join    (
    select  shop_id
            ,local_date
            ,sum(order_cnt) as order_cnt
    from    (
        select  shop_id
                ,order_cnt
                ,date(date_timezone_convert(regional_date, regional_hour, 'SG', grass_region, "yyyy-MM-dd")) as local_date
        from    rcmd_feature.dws_sr_data_warehouse_tc_pb_realtime_feature_5min
        where   grass_region in (${grass_region})
          and   (
                        (
                                regional_date = date_sub(${regional_date}, 1)
                            and regional_hour BETWEEN 0 and 23
                        )
                    or  (
                                regional_date = ${regional_date}
                            and regional_hour <= ${regional_hour}
                        )
                )
          and   operation in ('omni_order')
    )
    group by shop_id, local_date
) as T2
on      T1.shop_id = T2.shop_id
and  T1.local_date = T2.local_date
WHERE  T2.order_cnt > COALESCE(T1.order_ovl, 0)
;
